mapper.select:
SELECT u.id, u.username, u.name, u.phone, u.status, u.image, u.update_time, d.name as deptName, r.name as roleName FROM user u LEFT JOIN dept d ON u.dept_id = d.id LEFT JOIN role r ON u.role_id = r.id
AND u.name LIKE concat('%',#{name},'%')
AND u.phone LIKE concat('%',#{phone},'%')
AND u.dept_id = #{deptId}
AND u.status = #{status}
ORDER BY u.update_time DESC

SELECT
    *
FROM user
WHERE username = #{username}
OR phone = #{phone}
OR email = #{email}
LIMIT 1
